import sys

def solve():
    try:
        line1 = sys.stdin.readline().strip()
        if not line1:
            return
        x1, y1 = map(int, line1.split())

        line2 = sys.stdin.readline().strip()
        if not line2:
            return
        x2, y2 = map(int, line2.split())
    except ValueError:
        return

    dx = abs(x1 - x2)
    dy = abs(y1 - y2)

    if dx == 0 or dy == 0:
        result = 2 * (dx + dy + 2)
    else:
        result = 2 * (dx + dy + 2)

    print(result)

if __name__ == "__main__":
    solve()

